#!/usr/bin/env python3
"""Write docs/AGENTS.md from studio/agents.json and the vault skill files,
so the roster always matches what actually runs."""
import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
cfg = json.loads((ROOT / "studio/agents.json").read_text())["agents"]
lines = [
    "# Agent roster",
    "",
    "Generated by `scripts/agent_roster.py` from `studio/agents.json` and `vault/.claude/skills/*/SKILL.md`. Do not edit by hand.",
    "",
    "| Agent | Job | Output | Model | Vault sections it may read | Tools |",
    "|---|---|---|---|---|---|",
]
for name, a in cfg.items():
    if name == "bridge-test":
        continue
    sp = ROOT / f"vault/.claude/skills/{name}/SKILL.md"
    if not sp.is_file():
        sp = ROOT / f"vault/.claude/agents/{name}.md"
    skill = sp.read_text()
    m = re.search(r"^description: (.*)$", skill, re.M)
    job = m.group(1).split(". Run by")[0].replace(f"{name.capitalize()}'s job. ", "") if m else ""
    tools = ", ".join(a.get("allowed_tools", []))
    secs = ", ".join(a.get("allowed_sections", []))
    lines.append(f"| {name.capitalize()} | {job} | `{a.get('output')}` | {a['model']} | {secs} | {tools} |")
lines += [
    "",
    "Every agent: reads `00-Start-Here/index.md` first; cannot edit vault notes (deny rules);",
    "runs with `--permission-mode dontAsk` so any tool not listed is refused;",
    "runs under a hard dollar cap Andrew approved; writes `gate.json`, which the studio",
    "re-checks itself (`scripts/gates/check_stage.py`) before anything reaches the review queue.",
    "",
    "Gate checks per agent are in each skill file under `## Gate`.",
]
(ROOT / "docs/AGENTS.md").write_text("\n".join(lines) + "\n")
print(f"wrote docs/AGENTS.md with {len(cfg) - 1} agents")
